{
  "scenario_title": "Monthly construction cost indices and building permit issuances across regional markets by the National Statistics Bureau, 2022–2024",
  "data_context": "The National Statistics Bureau compiled monthly construction producer price indices, component input costs, and municipal building permit authorizations from January 2022 to June 2024. The data was collected under the national economic surveillance framework to evaluate cost push pressures, tracking how escalating material prices versus rising unionized labour rates affect residential and commercial building activity across macro-regions.",
  "script": "dim(\"country_zone\", [\"North & East\", \"South & West\"],\n    weights=[0.55, 0.45], group=\"geography\")\ndim(\"region\", [\"Northern Metro\", \"Eastern Industrial\", \"Southern Coastal\", \"Western Uplands\"],\n    parent=\"country_zone\",\n    weights={\"North & East\": [0.60, 0.40, 0.0, 0.0],\n             \"South & West\": [0.0, 0.0, 0.55, 0.45]},\n    group=\"geography\")\n\ndim(\"sector\", [\"Residential\", \"Non-Residential\"],\n    weights=[0.60, 0.40], group=\"sector_hierarchy\")\ndim(\"building_type\", [\"Single-Family Houses\", \"Multi-Family Apartments\", \"Commercial & Retail\", \"Industrial & Logistics\"],\n    parent=\"sector\",\n    weights={\"Residential\": [0.55, 0.45, 0.0, 0.0],\n             \"Non-Residential\": [0.0, 0.0, 0.50, 0.50]},\n    group=\"sector_hierarchy\")\n\ntime(\"report_month\", start=\"2022-01-01\", end=\"2024-06-01\", freq=\"monthly\")\n\nmeasure(\"material_cost_index\",\n        \"108.0 + 0.015 * report_month + 5.5 * [sector=Residential] + 3.8 * [country_zone=North & East] + gaussian(0, 2.2)\",\n        unit=\"index (2021=100)\", additive=False)\nmeasure(\"labour_cost_index\",\n        \"102.0 + 0.024 * report_month + 3.2 * [sector=Non-Residential] + 4.5 * [region=Northern Metro] + gaussian(0, 1.8)\",\n        unit=\"index (2021=100)\", additive=False)\nmeasure(\"cost_growth_gap\",\n        \"labour_cost_index - material_cost_index\",\n        unit=\"percentage points\", additive=False)\nmeasure(\"permits_issued\",\n        \"poisson(48 + 16 * [sector=Residential] + 12 * [region=Northern Metro] - 0.014 * report_month)\",\n        unit=\"permits\", additive=True)\n\nemit(720)",
  "intents": [
    {
      "sentence": "How did material and labour cost indices evolve over the two and a half year surveillance period",
      "columns": [
        "report_month",
        "material_cost_index"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "Which building types face the highest labour to material cost growth gap",
      "columns": [
        "building_type",
        "cost_growth_gap"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    },
    {
      "sentence": "How does the volume of permits issued correlate with rising material cost indices",
      "columns": [
        "material_cost_index",
        "permits_issued"
      ],
      "aggregate": "NONE",
      "family": "relation"
    },
    {
      "sentence": "Total building permits issued across geographical regions",
      "columns": [
        "region",
        "permits_issued"
      ],
      "aggregate": "SUM",
      "family": "comparison"
    }
  ]
}
